var plan = PlanValidator.load_plan_file("res://tests/fixtures/ai_plans/fixture_custodes_lions_crucible.json")
if plan.is_empty():
	return "NO_PLAN"
var verdict = PlanValidator.validate_plan(plan)
if not verdict.get("valid", false):
	return "INVALID: " + "; ".join(verdict.get("errors", []))
AIDecisionMaker.set_player_plan(1, plan)
AIDecisionMaker.set_player_plan(2, plan)
return str(plan.get("name", ""))

var p1 = AIDecisionMaker.get_player_plan(1)
var p2 = AIDecisionMaker.get_player_plan(2)
return not p1.is_empty() and not p2.is_empty() and AIDecisionMaker.plans_enabled()

var latch = GameState.get_meta("pm2a_latch", {})
for uid in GameState.state["units"]:
	var u = GameState.state["units"][uid]
	if int(u.get("status", 0)) == 0:
		continue
	if latch.has(uid):
		continue
	var pts = []
	for m in u.get("models", []):
		var p = m.get("position", null)
		if p == null:
			pts.append(null)
		elif p is Vector2:
			pts.append([p.x, p.y])
		else:
			pts.append([float(p.get("x", 0.0)), float(p.get("y", 0.0))])
	latch[uid] = pts
GameState.set_meta("pm2a_latch", latch)
if latch.size() >= 22 and AIPlayer.enabled:
	# Deployment is done. Stand the AI down so the board FREEZES on the
	# plan-driven formation for the screenshot below - otherwise the game
	# rolls on into the movement phase and the evidence shot shows units that
	# have already moved. Setting `enabled` directly (rather than
	# reconfiguring) keeps _all_decision_records, which the asserts read.
	AIPlayer.enabled = false
	print("SCENARIO pm2a froze AI after deployment (%d units latched)" % latch.size())
return latch.size()

