var plan = PlanValidator.load_plan_file("res://tests/fixtures/ai_plans/fixture_custodes_lions_crucible.json")
var latch = GameState.get_meta("pm2a_latch", {})
var ok = 0
var total = 0
var worst = 0.0
for placement in plan["deployment"]["placements"]:
	var pid = str(placement["unit"])
	var authored = placement["models_inches"]
	for player in [1, 2]:
		var live = pid if player == 1 else pid + "_P2"
		if not latch.has(live):
			continue
		var pts = latch[live]
		total += 1
		var d = 0.0
		for i in range(mini(authored.size(), pts.size())):
			if pts[i] == null:
				d = 999.0
				break
			var wx = float(authored[i][0])
			var wy = float(authored[i][1])
			if player == 2:
				wx = 44.0 - wx
				wy = 60.0 - wy
			var got = Vector2(float(pts[i][0]) / 40.0, float(pts[i][1]) / 40.0)
			d = maxf(d, Vector2(wx, wy).distance_to(got))
		if d <= 0.5:
			ok += 1
		worst = maxf(worst, d)
print("SCENARIO pm2a adherence %d/%d units within 0.5in, worst %.3fin" % [ok, total, worst])
return ok

var per_seat = {1: 0, 2: 0}
for batch in AIPlayer._all_decision_records:
	var seat = int(batch.get("player", 0))
	for rec in batch.get("records", []):
		if str(rec.get("decision_type", "")) != "deployment":
			continue
		if str(rec.get("context", {}).get("source", "")).begins_with("plan:"):
			per_seat[seat] = int(per_seat.get(seat, 0)) + 1
print("SCENARIO pm2a plan deployment records: seat1=%d seat2=%d" % [per_seat.get(1, 0), per_seat.get(2, 0)])
return mini(int(per_seat.get(1, 0)), int(per_seat.get(2, 0)))

var mirrored = 0
for batch in AIPlayer._all_decision_records:
	for rec in batch.get("records", []):
		var ctx = rec.get("context", {})
		if str(rec.get("decision_type", "")) == "deployment" and bool(ctx.get("seat_mirrored", false)):
			mirrored += 1
print("SCENARIO pm2a seat-mirrored deployments: %d" % mirrored)
return mirrored

var latch = GameState.get_meta("pm2a_latch", {})
var poly = PackedVector2Array()
for zone in GameState.state["board"]["deployment_zones"]:
	if int(zone.get("player", 0)) == 2:
		for p in zone["poly"]:
			poly.append(Vector2(float(p["x"]) * 40.0, float(p["y"]) * 40.0))
		break
var outside = 0
var checked = 0
for uid in latch:
	if not str(uid).ends_with("_P2"):
		continue
	for p in latch[uid]:
		if p == null:
			continue
		checked += 1
		if not Geometry2D.is_point_in_polygon(Vector2(float(p[0]), float(p[1])), poly):
			outside += 1
print("SCENARIO pm2a seat-2 models inside own zone: %d/%d" % [checked - outside, checked])
return outside
